const messageText = $input.item.json.message.text;
const chatId = $input.item.json.message.chat.id;

let lotName = '';
let coordinates = [];

try {
  const firstBracketIndex = messageText.indexOf('[');
  if (firstBracketIndex === -1) throw new Error('No se encontraron coordenadas en el formato esperado');

  lotName = messageText.substring(0, firstBracketIndex).trim();

  if (lotName.startsWith('/lote')) lotName = lotName.replace('/lote', '').trim();
  if (lotName.startsWith('/coordenada')) lotName = lotName.replace('/coordenada', '').trim();
  if (lotName.startsWith('/crearlote')) lotName = lotName.replace('/crearlote', '').trim();

  const coordString = messageText.substring(firstBracketIndex);
  coordinates = JSON.parse(coordString);

  if (!Array.isArray(coordinates) || coordinates.length < 3)
    throw new Error('Se necesitan al menos 3 coordenadas para formar un polígono');

  // Calcular el área usando la fórmula de Shoelace con conversión a metros
  // Primero calculamos el centroide para obtener la latitud promedio
  let sumLat = 0;
  for (let i = 0; i < coordinates.length; i++) {
    sumLat += coordinates[i].lat;
  }
  const avgLat = sumLat / coordinates.length;

  // Factor de conversión de grados a metros
  const latToMeters = 111320; // 1 grado de latitud ≈ 111320 metros
  const lngToMeters = 111320 * Math.cos(avgLat * Math.PI / 180); // ajustado por latitud

  // Convertir coordenadas a metros relativos
  const coordsInMeters = coordinates.map(coord => ({
    x: coord.lng * lngToMeters,
    y: coord.lat * latToMeters
  }));

  // Cerrar el polígono si no está cerrado
  const firstCoord = coordsInMeters[0];
  const lastCoord = coordsInMeters[coordsInMeters.length - 1];
  if (firstCoord.x !== lastCoord.x || firstCoord.y !== lastCoord.y) {
    coordsInMeters.push(firstCoord);
  }

  // Aplicar fórmula de Shoelace
  let area = 0;
  for (let i = 0; i < coordsInMeters.length - 1; i++) {
    const x1 = coordsInMeters[i].x;
    const y1 = coordsInMeters[i].y;
    const x2 = coordsInMeters[i + 1].x;
    const y2 = coordsInMeters[i + 1].y;
    area += (x1 * y2 - x2 * y1);
  }
  area = Math.abs(area / 2);

  // Retornar resultado con formato correcto para el backend
  return [{
    json: {
      nombre: lotName,
      area: Math.round(area * 100) / 100,
      estado: 'Activo',
      coordenadas: {
        type: 'polygon',
        coordinates: coordinates
      },
      chatId: chatId
    }
  }];

} catch (error) {
  return [{
    json: {
      error: true,
      errorMessage: error.message,
      chatId: chatId,
      originalMessage: messageText
    }
  }];
}

