// Obtener los lotes del backend desde la propiedad data
const response = $input.first().json;
const lotes = response.data;

// Obtener el chatId del trigger original
const chatId = $('Telegram Trigger').first().json.message.chat.id;

// Verificar si hay lotes
if (!lotes || !Array.isArray(lotes) || lotes.length === 0) {
  return [{
    json: {
      chatId: chatId,
      message: "📋 No hay lotes registrados en el sistema."
    }
  }];
}

// Formatear la lista de lotes
let message = "📋 *Lista de Lotes Registrados*\n\n";

lotes.forEach((lote, index) => {
  message += `${index + 1}. *${lote.nombre}*\n`;
  message += `   📏 Área: ${lote.area} m²\n`;
  message += `   📊 Estado: ${lote.estado}\n`;

  // Si hay coordenadas, mostrar la cantidad de puntos
  if (lote.coordenadas && lote.coordenadas.coordinates) {
    const numPuntos = lote.coordenadas.coordinates.length;
    message += `   📍 Puntos: ${numPuntos}\n`;
  }

  message += "\n";
});

message += `\n✅ Total de lotes: ${lotes.length}`;

return [{
  json: {
    chatId: chatId,
    message: message
  }
}];

// Obtener las actividades del backend
const allItems = $input.all();
let actividades = [];

if (allItems.length > 1) {
  actividades = allItems.map(item => item.json);
} else if (allItems.length === 1) {
  const inputData = allItems[0].json;

  if (Array.isArray(inputData)) {
    actividades = inputData;
  } else if (inputData.data && Array.isArray(inputData.data)) {
    actividades = inputData.data;
  } else if (inputData.id && inputData.titulo) {
    actividades = [inputData];
  }
}

const chatId = $('Telegram Trigger').first().json.message.chat.id;

if (!actividades || actividades.length === 0) {
  return [{
    json: {
      chatId: chatId,
      message: "📅 No hay actividades registradas en el sistema."
    }
  }];
}

// Formatear la lista de actividades
let message = "📅 *Lista de Actividades Registradas*\n\n";

actividades.forEach((actividad, index) => {
  message += `${index + 1}. *${actividad.titulo || 'Sin título'}*\n`;
  message += `   ID: ${actividad.id}\n`;

  if (actividad.descripcion) {
    message += `   📝 ${actividad.descripcion}\n`;
  }

  if (actividad.fecha) {
    message += `   📆 Fecha: ${actividad.fecha}\n`;
  }

  if (actividad.cultivo && actividad.cultivo.nombre) {
    message += `   🌱 Cultivo: ${actividad.cultivo.nombre}\n`;
  }

  if (actividad.estado) {
    const estadoEmoji = actividad.estado === 'pendiente' ? '⏳' : actividad.estado === 'completada' ? '✅' : '📊';
    message += `   ${estadoEmoji} Estado: ${actividad.estado}\n`;
  }

  // Parsear asignados
  if (actividad.asignados) {
    try {
      const asignadosArray = JSON.parse(actividad.asignados);
      if (asignadosArray.length > 0) {
        message += `   👥 Asignados: ${asignadosArray.join(', ')}\n`;
      }
    } catch (e) {
      message += `   👥 Asignados: ${actividad.asignados}\n`;
    }
  }

  // Mostrar archivos iniciales de la actividad
  if (actividad.archivoInicial) {
    try {
      const archivosInicialesArray = JSON.parse(actividad.archivoInicial);
      if (archivosInicialesArray.length > 0) {
        message += `\n   📎 *Archivos de la actividad (${archivosInicialesArray.length}):*\n`;
        archivosInicialesArray.forEach((archivo, aIndex) => {
          // Extraer nombre limpio del archivo (después del timestamp y hash)
          const partes = archivo.split('-');
          const nombreLimpio = partes.length >= 3 ? partes.slice(2).join('-') : archivo;
          message += `      ${aIndex + 1}. ${nombreLimpio}\n`;
          message += `         📥 /descargar_act_${actividad.id}_${archivo}\n`;
        });
      }
    } catch (e) {
      // Si no se puede parsear, ignorar
    }
  }

  // Mostrar respuestas si existen
  if (actividad.respuestas && Array.isArray(actividad.respuestas) && actividad.respuestas.length > 0) {
    message += `\n   💬 *Respuestas (${actividad.respuestas.length}):*\n`;

    actividad.respuestas.forEach((respuesta, rIndex) => {
      message += `\n   ${rIndex + 1}) `;

      if (respuesta.usuario) {
        message += `👤 ${respuesta.usuario.nombre} ${respuesta.usuario.apellidos}\n`;
      }

      if (respuesta.descripcion) {
        message += `      📝 ${respuesta.descripcion}\n`;
      }

      if (respuesta.fechaEnvio) {
        message += `      🕒 ${respuesta.fechaEnvio}\n`;
      }

      if (respuesta.estado) {
        message += `      📊 Estado: ${respuesta.estado}\n`;
      }

      // Indicar si hay archivos adjuntos en la respuesta
      if (respuesta.archivos) {
        try {
          const archivosArray = JSON.parse(respuesta.archivos);
          if (archivosArray.length > 0) {
            message += `      📎 ${archivosArray.length} archivo(s) adjunto(s)\n`;
            message += `      📥 Para descargar: /descargar_${actividad.id}_${respuesta.id}\n`;
          }
        } catch (e) {
          message += `      📎 Archivos adjuntos\n`;
          message += `      📥 Para descargar: /descargar_${actividad.id}_${respuesta.id}\n`;
        }
      }
    });
  } else {
    message += `\n   ℹ️ Sin respuestas aún\n`;
  }

  message += "\n";
});

message += `✅ Total de actividades: ${actividades.length}`;

return [{
  json: {
    chatId: chatId,
    message: message
  }
}];

// Extraer actividadId y respuestaId del comando /descargar_X_Y
const messageText = $input.first().json.message.text;
const chatId = $input.first().json.message.chat.id;

// Formato esperado: /descargar_actividadId_respuestaId
const parts = messageText.split('_');

if (parts.length !== 3) {
  return [{
    json: {
      error: true,
      chatId: chatId,
      message: '❌ Formato de comando inválido. Usa: /descargar_actividadId_respuestaId'
    }
  }];
}

const actividadId = parseInt(parts[1]);
const respuestaId = parseInt(parts[2]);

if (isNaN(actividadId) || isNaN(respuestaId)) {
  return [{
    json: {
      error: true,
      chatId: chatId,
      message: '❌ IDs inválidos. Deben ser números.'
    }
  }];
}

return [{
  json: {
    actividadId: actividadId,
    respuestaId: respuestaId,
    chatId: chatId
  }
}];

// Procesar la respuesta del backend y preparar archivos para enviar
const respuesta = $input.first().json;
const chatId = $('Extraer IDs de Descarga').first().json.chatId;

// Verificar si hay archivos
if (!respuesta.archivos) {
  return [{
    json: {
      chatId: chatId,
      message: '❌ Esta respuesta no tiene archivos adjuntos.',
      hasFiles: false
    }
  }];
}

// Parsear el array de archivos
let archivosArray = [];
try {
  archivosArray = JSON.parse(respuesta.archivos);
} catch (e) {
  return [{
    json: {
      chatId: chatId,
      message: '❌ Error al procesar los archivos adjuntos.',
      hasFiles: false
    }
  }];
}

if (!Array.isArray(archivosArray) || archivosArray.length === 0) {
  return [{
    json: {
      chatId: chatId,
      message: '❌ Esta respuesta no tiene archivos adjuntos.',
      hasFiles: false
    }
  }];
}

// Preparar información de la respuesta
const usuario = respuesta.usuario ? `${respuesta.usuario.nombre} ${respuesta.usuario.apellidos}` : 'Usuario desconocido';
const descripcion = respuesta.descripcion || 'Sin descripción';
const fechaEnvio = respuesta.fechaEnvio || 'Fecha desconocida';

// Crear un item por cada archivo usando el endpoint correcto
const items = archivosArray.map((archivo, index) => {
  // El nombre del archivo viene del backend
  const nombreArchivo = archivo;

  // URL del endpoint de descarga del backend
  const baseUrl = 'https://fleta-unfelonious-unpatronizingly.ngrok-free.dev';
  const fileUrl = `${baseUrl}/actividades/descargar/${nombreArchivo}`;

  return {
    json: {
      chatId: chatId,
      fileUrl: fileUrl,
      fileName: nombreArchivo,
      caption: `📎 Archivo ${index + 1} de ${archivosArray.length}\n👤 ${usuario}\n📝 ${descripcion}\n🕒 ${fechaEnvio}`,
      hasFiles: true
    }
  };
});

return items;

// Extraer actividadId y nombre de archivo del comando /descargar_act_X_filename
const messageText = $input.first().json.message.text;
const chatId = $input.first().json.message.chat.id;

// Formato esperado: /descargar_act_actividadId_nombreArchivo
const parts = messageText.split('_');

if (parts.length < 4) {
  return [{
    json: {
      error: true,
      chatId: chatId,
      message: '❌ Formato de comando inválido.'
    }
  }];
}

const actividadId = parseInt(parts[2]);
const nombreArchivo = parts.slice(3).join('_'); // Reunir el nombre del archivo

if (isNaN(actividadId)) {
  return [{
    json: {
      error: true,
      chatId: chatId,
      message: '❌ ID de actividad inválido.'
    }
  }];
}

return [{
  json: {
    actividadId: actividadId,
    nombreArchivo: nombreArchivo,
    chatId: chatId
  }
}];
